#[derive(Accounts)]
pub struct Withdraw<'info> {
    pub vault: AccountInfo<'info>,
    pub authority: Signer<'info>,
}

vulnerable_snippet:
function withdraw() public {
    uint amount = balances[msg.sender];
    require(amount > 0);
    (bool success, ) = msg.sender.call{value: amount}("");
    require(success);
    balances[msg.sender] = 0;
}

patched_snippet:
function withdraw() public nonReentrant {
    uint amount = balances[msg.sender];
    require(amount > 0);
    balances[msg.sender] = 0; // Checks-Effects-Interactions
    (bool success, ) = msg.sender.call{value: amount}("");
    require(success, "Transfer failed");
}

prompt:
Audit the following smart contract code and identify any Reentrancy vulnerabilities:

function withdraw() public {
    uint amount = balances[msg.sender];
    require(amount > 0);
    (bool success, ) = msg.sender.call{value: amount}("");
    require(success);
    balances[msg.sender] = 0;
}

completion:
### Vulnerability Analysis
- Category: Reentrancy (CWE-841)
- Severity: CRITICAL
- Explanation: State update performed after external call allowing recursive re-entrant invocation.

### Patched Implementation:
```solidity
function withdraw() public nonReentrant {
    uint amount = balances[msg.sender];
    require(amount > 0);
    balances[msg.sender] = 0; // Checks-Effects-Interactions
    (bool success, ) = msg.sender.call{value: amount}("");
    require(success, "Transfer failed");
}
```

vulnerable_snippet:
function setFeeRecipient(address newRecipient) public {
    feeRecipient = newRecipient;
}

patched_snippet:
function setFeeRecipient(address newRecipient) public onlyOwner {
    require(newRecipient != address(0), "Invalid zero address");
    feeRecipient = newRecipient;
    emit FeeRecipientUpdated(newRecipient);
}

prompt:
